import type {editor, Selection} from 'monaco-editor'

// Custom executeEdits to workaround readOnly on the Editor and update the text buffer
export function executeEdits(
  editor: editor.IStandaloneCodeEditor | editor.IStandaloneDiffEditor,
  model: editor.ITextModel,
  edits: editor.IIdentifiedSingleEditOperation[],
  endCursorState?: editor.ICursorStateComputer | Selection[],
) {
  let cursorStateComputer
  if (!endCursorState) {
    cursorStateComputer = () => null
  } else if (Array.isArray(endCursorState)) {
    cursorStateComputer = () => endCursorState
  } else {
    cursorStateComputer = endCursorState
  }
  model.pushEditOperations(editor.getSelections(), edits, cursorStateComputer)
}
